func RangedUnsignedMeasureMessages(values []*RangedUnsigned, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !RangedUnsignedSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func RangedUnsignedSaveMessages(values []*RangedUnsigned, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !RangedUnsignedSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	if w.Over != 0 {
		if report != nil {
			report.Refuse(TableRefuseInvalidValue, "")
		}
		return -1
	}
	return 2 + w.Bits/8
}
